const fs = require("fs");

const pkg = require("./package.json");
const source = fs.readFileSync("index.js", "utf8");

fs.rmSync("dist", { recursive: true, force: true });
fs.mkdirSync("dist");

const banner = `/*! ${pkg.name} v${pkg.version} | MIT | reproducible build */\n`;
fs.writeFileSync("dist/my-package.js", banner + source);
console.log("Built dist/my-package.js");
